from pptx import Presentation
from pptx.util import Inches, Emu
prs = Presentation('/app/output/final_deck.pptx')
print(f'Slide dimensions: {prs.slide_width} x {prs.slide_height} EMU')
print(f'Aspect ratio: {prs.slide_width / prs.slide_height:.4f} (16:9 = {16/9:.4f})')
print(f'Total slides: {len(prs.slides)}')
print()
for i, slide in enumerate(prs.slides):
    shapes = slide.shapes
    text_shapes = [s for s in shapes if s.has_text_frame]
    print(f'Slide {i+1}: {len(shapes)} shapes, {len(text_shapes)} with text')
    # Check for overflow or negative positions
    for s in shapes:
        if s.left < 0 or s.top < 0:
            print(f'  WARNING: shape at negative position ({s.left}, {s.top})')
        if s.left + s.width > prs.slide_width + Inches(0.5):
            print(f'  WARNING: shape extends beyond right edge')
        if s.top + s.height > prs.slide_height + Inches(0.5):
            print(f'  WARNING: shape extends beyond bottom edge')
    # Print first text shape as title indicator
    for s in text_shapes:
        if s.has_text_frame and s.text_frame.text.strip():
            print(f'  Title/First: {s.text_frame.text[:80]}')
            break
    # Check for table
    for s in shapes:
        if s.has_table:
            t = s.table
            print(f'  TABLE: {len(t.rows)} rows x {len(t.columns)} cols')
    # Check for chart
    if hasattr(shapes, '_spTree'):
        pass
    for s in shapes:
        if s.has_chart:
            print(f'  CHART: {s.chart.chart_type}')
    print()
"

